class Solution {
public:
    int networkBecomesIdle(vector<vector<int>>& edges, vector<int>& patience) {
        int n = patience.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<int> dist(n, -1);
        vector<int> q;
        dist[0] = 0;
        q.push_back(0);
        int head = 0;
        while (head < (int)q.size()) {
            int u = q[head++];
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push_back(v);
                }
            }
        }
        long long ans = 0;
        for (int i = 1; i < n; i++) {
            long long d = dist[i];
            long long p = patience[i];
            long long lastSend = ((2 * d - 1) / p) * p;
            long long lastReply = lastSend + 2 * d;
            ans = max(ans, lastReply);
        }
        return (int)(ans + 1);
    }
};
